(()=>{
'use strict';
const L={manifest:null,build:'',cache:new Map(),timer:null,refreshing:false,members:null,activeGroup:'',sectorTimer:null};
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const n=v=>v==null||v===''||!Number.isFinite(Number(v))?null:Number(v);
const fmt=(v,d=2)=>n(v)==null?'—':Number(v).toLocaleString('zh-TW',{maximumFractionDigits:d});
const pct=v=>n(v)==null?'—':`${Number(v)>0?'+':''}${fmt(v,2)}%`;
const signed=(v,d=2)=>n(v)==null?'—':`${Number(v)>0?'+':''}${fmt(v,d)}`;
const view=()=>document.querySelector('.tab.active')?.dataset.view||'intraday';
const regime={BROAD_RISK_ON:'全面偏多',SELECTIVE_RISK_ON:'選股偏多',NEUTRAL:'中性',DEFENSIVE:'防守',RISK_OFF:'風險關閉'};
const freshness={LIVE:'即時',FRESH:'盤後定格',FROZEN:'收盤定格',STALE:'過期',UNKNOWN:'未知'};
const marketKey=v=>(v==='intraday'||v==='daytrade')?'market_intraday_context':'market_close_context';
async function json(url){const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`${url} HTTP ${r.status}`);return r.json()}
async function manifest(force=false){if(L.manifest&&!force)return L.manifest;const m=await json(`./data/current_manifest.json?liveui=${Date.now()}`);if(L.build&&L.build!==m.active_build_id){L.cache.clear();L.members=null}L.manifest=m;L.build=m.active_build_id||'';return m}
async function dataset(key,force=false){const m=await manifest(force),meta=m.datasets?.[key];if(!meta)return null;const ck=`${m.active_build_id}:${key}`;if(force)L.cache.delete(ck);if(L.cache.has(ck))return L.cache.get(ck);const x=await json(meta.url);if(x?.build_id&&x.build_id!==m.active_build_id)throw new Error(`${key} build_id mismatch`);L.cache.set(ck,x);return x}
function clockText(v){const s=String(v||'');const m=s.match(/(?:T|\s)(\d{2}:\d{2})/)||s.match(/^(\d{2}:\d{2})/);return m?m[1]:'—'}
function pointMove(close,changePct){const c=n(close),p=n(changePct);if(c==null||p==null||p<=-100)return null;const prev=c/(1+p/100);return c-prev}
function tone(v){return n(v)==null?'':Number(v)>0?'live-pulse-rise':Number(v)<0?'live-pulse-fall':''}
function style(){if($('#liveUi20261001Style'))return;const s=document.createElement('style');s.id='liveUi20261001Style';s.textContent=`
#marketPulse{display:none!important}.top{position:relative!important;top:auto!important}.tabs{top:62px!important;z-index:40!important}
#livePinnedBar{position:sticky;top:0;z-index:50;display:grid;grid-template-columns:minmax(92px,1.2fr) minmax(82px,1fr) minmax(76px,.9fr) auto;gap:6px;align-items:center;min-height:62px;padding:7px 10px;background:#253c33;color:#fff;box-shadow:0 2px 9px rgba(0,0,0,.18)}
.live-pulse-item{min-width:0}.live-pulse-item span{display:block;opacity:.76;font-size:.64rem}.live-pulse-item b{display:block;font-size:.83rem;line-height:1.15;white-space:nowrap}.live-pulse-item small{display:block;opacity:.82;font-size:.6rem;margin-top:2px;white-space:nowrap;font-variant-numeric:tabular-nums}.live-pulse-rise{color:#ffb5ad!important}.live-pulse-fall{color:#9fddbd!important}
#livePulseRefresh{border:1px solid rgba(255,255,255,.38);background:rgba(255,255,255,.08);color:#fff;border-radius:9px;padding:8px 7px;font-size:.66rem;font-weight:850;white-space:nowrap}#livePulseRefresh:disabled{opacity:.5}
.live-sector-preview{margin-top:5px!important;color:#4d6258!important;line-height:1.45!important;font-size:.7rem!important}.live-sector-members{margin-top:8px;padding-top:7px;border-top:1px dashed #dfe5df}.live-sector-title{font-size:.72rem;color:#607269;margin-bottom:6px}.live-sector-list{display:flex;flex-wrap:wrap;gap:6px}.live-member-btn{border:1px solid #d9e2dc;background:#fff;border-radius:999px;padding:6px 9px;font-size:.72rem;color:#355247}.live-member-btn:active{transform:scale(.98)}
.live-sector-rank{margin-top:9px;padding:9px 10px;border-radius:10px;background:var(--soft);border:1px solid var(--line)}.live-sector-rank-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:6px}.live-sector-rank-head b{font-size:.82rem}.live-sector-rank-head span{font-size:.68rem;color:var(--muted)}.live-sector-rank-list{display:grid;gap:5px}.live-sector-rank-row{display:grid;grid-template-columns:auto 1fr;gap:7px;align-items:center;border:1px solid var(--line);background:var(--card);border-radius:9px;padding:7px 8px;cursor:pointer;color:var(--ink);text-align:left}.live-sector-rank-row strong{font-size:.76rem}.live-sector-rank-row small{display:block;color:var(--muted);font-size:.65rem;margin-top:2px}
@media(max-width:560px){#livePinnedBar{grid-template-columns:1.08fr 1fr .88fr auto;padding:6px 8px;gap:4px}.live-pulse-item b{font-size:.76rem}#livePulseRefresh{padding:7px 6px;font-size:.62rem}.tabs{top:62px!important}}
`;document.head.appendChild(s)}
function ensureBar(){style();let bar=$('#livePinnedBar');if(bar)return bar;bar=document.createElement('div');bar.id='livePinnedBar';bar.setAttribute('aria-label','市場資訊');bar.innerHTML='<div class="live-pulse-item"><span>加權指數</span><b>—</b><small>讀取中</small></div><div class="live-pulse-item"><span>櫃買指數</span><b>—</b><small>讀取中</small></div><div class="live-pulse-item"><span>環境分</span><b>—</b><small>讀取中</small></div><button id="livePulseRefresh" type="button">重新整理</button>';$('#app')?.prepend(bar);return bar}
function indexCell(label,q,ctxPct){const close=n(q?.close),chg=n(q?.change_pct)??n(ctxPct),move=pointMove(close,chg),src=String(q?.source||'');if(close==null)return `<span>${esc(label)}</span><b>—</b><small class="${tone(chg)}">${pct(chg)} · 同日點位待補</small>`;return `<span>${esc(label)}</span><b>${fmt(close,2)}</b><small class="${tone(chg)}">${signed(move,2)} · ${pct(chg)}${src?` · ${esc(src==='MIS_INTRADAY'?'即時':'收盤')}`:''}</small>`}
async function renderBar(force=false){try{const v=view(),m=await manifest(force),[ctx,iq]=await Promise.all([dataset(marketKey(v),force),dataset('index_quote',force).catch(()=>null)]),valid=iq&&iq.build_id===m.active_build_id&&String(iq.trade_date||'').slice(0,10)===String(m.trade_date||'').slice(0,10),ta=valid?iq.taiex:null,ot=valid?iq.otc:null,b=ensureBar(),cells=b.querySelectorAll('.live-pulse-item'),tc=ctx?.components?.taiex?.change_pct,oc=ctx?.components?.otc?.change_pct,clock=clockText(ctx?.metrics?.quote_snapshot_time||ctx?.as_of||m.trade_date),fr=freshness[ctx?.freshness]||ctx?.freshness||'—';if(cells[0])cells[0].innerHTML=indexCell('加權指數',ta,tc);if(cells[1])cells[1].innerHTML=indexCell('櫃買指數',ot,oc);if(cells[2])cells[2].innerHTML=`<span>環境分</span><b>${fmt(ctx?.market_score,1)}/15</b><small>${esc(regime[ctx?.market_regime]||ctx?.market_regime||'—')} · ${esc(fr)} ${esc(clock)}</small>`;b.dataset.build=m.active_build_id||'';b.dataset.tradeDate=m.trade_date||'';b.dataset.indexSource=valid?'ATOMIC_INDEX_QUOTE':'NO_VALID_INDEX_QUOTE'}catch(e){console.warn('live pinned bar',e)}}
async function memberData(force=false){if(L.members&&!force)return L.members;try{const m=await manifest(force),x=await json(`./data/sector-members.json?members=${Date.now()}`);if(x?.build_id&&x.build_id!==m.active_build_id)return null;L.members=x;return x}catch{return null}}
function chipGroup(chip){const t=chip?.querySelector('b')?.textContent?.trim()||'';return t.replace(/^[^\p{L}\p{N}]+/u,'').trim()}
function groupsFor(v,data){const key=v==='intraday'||v==='daytrade'?'intraday':'close';return data?.[key]?.groups||{}}
function scheduleSectorPatch(delay=180){clearTimeout(L.sectorTimer);L.sectorTimer=setTimeout(()=>patchSectors(),delay)}
async function patchSectors(){try{const data=await memberData(),groups=groupsFor(view(),data),chips=document.querySelectorAll('#sectorList .capital-chip');for(const chip of chips){const g=chipGroup(chip),xs=Array.isArray(groups[g])?groups[g]:[];chip.querySelectorAll('.live-sector-preview,.live-sector-members').forEach(x=>x.remove());if(!xs.length)continue;const preview=document.createElement('div');preview.className='live-sector-preview';preview.textContent=`族群股：${xs.slice(0,4).map(x=>`${x.code} ${x.name}`).join('・')}`;const hint=chip.querySelector('.capital-hint');if(hint)hint.before(preview);else chip.appendChild(preview);const more=chip.querySelector('.capital-more');if(more){const wrap=document.createElement('div');wrap.className='live-sector-members';wrap.innerHTML=`<div class="live-sector-title">同族群股票（${xs.length}檔）</div><div class="live-sector-list">${xs.slice(0,36).map(x=>`<button type="button" class="live-member-btn" data-live-stock="${esc(x.code)}">${esc(x.code)} ${esc(x.name)}</button>`).join('')}</div>${xs.length>36?'<div class="capital-hint">先顯示前 36 檔，其餘可用股票搜尋。</div>':''}`;more.appendChild(wrap)}}}catch(e){console.warn('sector member patch',e)}}
async function renderSectorRank(group){if(!group)return;try{const data=await memberData(),groups=groupsFor(view(),data),xs=Array.isArray(groups[group])?groups[group].slice(0,8):[],box=$('#sectorRankExplain');if(!box||L.activeGroup!==group)return;box.hidden=false;box.innerHTML=`<div class="live-sector-rank"><div class="live-sector-rank-head"><b>${esc(group)}｜同族群股票</b><span>前 ${xs.length}/${(groups[group]||[]).length} 檔</span></div><div class="live-sector-rank-list">${xs.length?xs.map((x,i)=>`<button type="button" class="live-sector-rank-row" data-live-stock="${esc(x.code)}"><b>${i+1}</b><span><strong>${esc(x.code)} ${esc(x.name)}</strong><small>點一下查看個股詳情</small></span></button>`).join(''):'<div class="muted">目前沒有可對應個股。</div>'}</div></div>`}catch(e){console.warn('sector rank patch',e)}}
async function softRefresh(){if(L.refreshing)return;L.refreshing=true;const top=$('#livePulseRefresh');if(top){top.disabled=true;top.textContent='更新中…'}try{const done=new Promise(resolve=>{let t=setTimeout(resolve,8000);document.addEventListener('radar:data-reloaded',()=>{clearTimeout(t);resolve()},{once:true})});const btn=$('#refreshBtn');if(btn)btn.click();else location.reload();await done;L.manifest=null;L.cache.clear();L.members=null;await renderBar(true);scheduleSectorPatch(250)}finally{L.refreshing=false;if(top){top.disabled=false;top.textContent='重新整理'}}}
async function check(){if(document.hidden||L.refreshing)return;try{const m=await json(`./data/current_manifest.json?autocheck=${Date.now()}`);if(L.build&&m.active_build_id&&m.active_build_id!==L.build)await softRefresh();else{L.manifest=m;L.build=m.active_build_id||L.build;await renderBar(true)}}catch(e){console.warn('live auto refresh',e)}}
function boot(){ensureBar();renderBar();scheduleSectorPatch(320);L.timer=setInterval(check,60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});document.addEventListener('radar:view-rendered',()=>{L.activeGroup='';renderBar();scheduleSectorPatch(280);setTimeout(()=>patchSectors(),700)});document.addEventListener('radar:data-reloaded',()=>{L.manifest=null;L.cache.clear();L.members=null;renderBar(true);scheduleSectorPatch(300)});document.addEventListener('click',e=>{if(e.target.closest?.('#livePulseRefresh')){softRefresh();return}const member=e.target.closest?.('[data-live-stock]');if(member){e.preventDefault();e.stopPropagation();document.dispatchEvent(new CustomEvent('radar:open-stock',{detail:{code:member.dataset.liveStock,source:'sector'}}));return}const chip=e.target.closest?.('#sectorList [data-capital-expand]');if(chip){L.activeGroup=chipGroup(chip);setTimeout(()=>renderSectorRank(L.activeGroup),120)}},true)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
